function sendSocket(message){if(!socket||socket.readyState!==WebSocket.OPEN){setInteractionStatus("OFFLINE",true);return false}socket.send(JSON.stringify(message));return true}
function sendText(){const input=$("#chat-input"),text=input.value.trim();if(!text)return;const request_id=crypto.randomUUID();if(sendSocket({type:"input.text",request_id,text})){addChat("user",text);input.value="";setInteractionStatus("SENDING")}}
function handleInteraction(msg){if(msg.kind==="interaction.status")setInteractionStatus(msg.status.toUpperCase());if(msg.kind==="interaction.busy"){setInteractionStatus(`BUSY · ${(msg.owner||"runtime").toUpperCase()}`,true);addChat("assistant",`Jarvis is busy with ${msg.owner||"another turn"}. Please try again.`)}if(msg.kind==="interaction.error"){setInteractionStatus("ERROR",true);addChat("assistant",`Error: ${msg.error}`)}if(msg.kind==="interaction.result"){if(msg.transcript)addChat("user",msg.transcript);addChat("assistant",msg.text);setInteractionStatus("READY");playAssistantAudio(msg)}}
function finishPlayback(msg){sendSocket({type:"tts.playback.finished",request_id:msg.request_id||crypto.randomUUID(),playback_token:msg.playback_token||""})}
function playAssistantAudio(msg){if(msg.audio){const player=new Audio(`data:${msg.audio_mime||"audio/wav"};base64,${msg.audio}`);player.onplay=()=>setInteractionStatus("SPEAKING");player.onended=()=>{setInteractionStatus("READY");finishPlayback(msg)};player.onerror=()=>speakBrowser(msg.text,msg);player.play().catch(()=>speakBrowser(msg.text,msg));return}speakBrowser(msg.text,msg)}
function speakBrowser(text,msg){if("speechSynthesis" in window&&text){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.onstart=()=>setInteractionStatus("SPEAKING");utterance.onend=()=>{setInteractionStatus("READY");finishPlayback(msg)};utterance.onerror=()=>finishPlayback(msg);speechSynthesis.speak(utterance);return}finishPlayback(msg)}
async function toggleRecording(){if(mediaRecorder&&mediaRecorder.state==="recording"){mediaRecorder.stop();return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=MediaRecorder.isTypeSupported("audio/webm;codecs=opus")?"audio/webm;codecs=opus":"audio/webm";audioChunks=[];mediaRecorder=new MediaRecorder(stream,{mimeType:mime});mediaRecorder.ondataavailable=e=>{if(e.data.size)audioChunks.push(e.data)};mediaRecorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());$("#voice-button").classList.remove("recording");setInteractionStatus("TRANSCRIBING");const blob=new Blob(audioChunks,{type:mime}),bytes=new Uint8Array(await blob.arrayBuffer());let binary="";for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));sendSocket({type:"input.audio",request_id:crypto.randomUUID(),mime_type:mime,audio:btoa(binary)})};mediaRecorder.start();$("#voice-button").classList.add("recording");setInteractionStatus("LISTENING")}catch(error){setInteractionStatus("MIC DENIED",true);addChat("assistant",`Microphone error: ${error.message}`)}}
$$("nav button").forEach(b=>b.onclick=()=>{$$("nav button,.view").forEach(x=>x.classList.remove("active"));b.classList.add("active");$("#"+b.dataset.view).classList.add("active");$("#title").textContent=titles[b.dataset.view]});
$("#memory-find").onclick=()=>loadMemory($("#memory-search").value);$("#memory-search").onkeydown=e=>{if(e.key==="Enter")loadMemory(e.target.value)};
$("#artifact-find").onclick=()=>loadArtifacts($("#artifact-search").value);$("#artifact-search").onkeydown=e=>{if(e.key==="Enter")loadArtifacts(e.target.value)};
$("#log-search").oninput=render;$("#log-level").onchange=render;
$("#settings-save").onclick=async()=>{try{const value=JSON.parse($("#settings-json").value);await api("/api/settings",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(value)});$("#settings-status").textContent="Saved. Restart Jarvis to apply."}catch(e){$("#settings-status").textContent=e.message}};
$("#memory-metric").onclick=e=>{e.stopPropagation();$("#memory-breakdown").classList.toggle("open")};document.addEventListener("click",()=>$("#memory-breakdown").classList.remove("open"));
$("#chat-send").onclick=sendText;$("#chat-input").onkeydown=e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendText()}};$("#voice-button").onclick=toggleRecording;
$("#runtime-sound-toggle").onclick=async()=>{const enabled=!runtimeSoundEnabled();localStorage.setItem("jarvis.runtimeSound",enabled?"on":"off");updateRuntimeSoundToggle();if(enabled&&await unlockRuntimeSound())playRuntimeSound("completed",true)};document.addEventListener("pointerdown",unlockRuntimeSound,{once:true});updateRuntimeSoundToggle();
$("#runtime-sound-test").onclick=async()=>{if(!runtimeSoundEnabled()){localStorage.setItem("jarvis.runtimeSound","on");updateRuntimeSoundToggle()}if(await unlockRuntimeSound())playRuntimeSound("completed",true)};
updateClock();setInterval(updateClock,1000);
setInterval(async()=>{try{[state.providers,state.abilities]=await Promise.all([api("/api/providers"),api("/api/abilities")]);renderProviders();renderAbilityMonitor()}catch(_){}},15000);
Promise.all([loadMemory(),loadArtifacts(),loadProjection(),loadAux()]).catch(console.error);connect();
